// Consolidate all user rows into a single item so subsequent Sheets reads
// run exactly once instead of once per user.
return [{ json: { users: items.map(i => i.json) } }];

// Fan out: returns 1 item per active user, each containing their full data context.
// items = all nudge rows; other sheets accessed via node references.

const { users, prescriptions, schedule_state } = $('Merge Schedule State').first().json;
const nudges = items.map(i => i.json);

// Next week Mon–Sun (workflow runs Monday morning, so next week = Mon+7 through Sun+13)
const daysToNextMonday = (8 - $now.weekday) % 7 || 7;
const nextMonday     = $now.plus({ days: daysToNextMonday }).startOf('day');
const nextWeekStart  = nextMonday.toISODate();
const nextWeekEnd    = nextMonday.plus({ days: 6 }).toISODate();

// Last week for summary stats (Mon–Sun ending yesterday)
const lastWeekStart  = $now.minus({ weeks: 1 }).startOf('week').toISODate();
const lastWeekEnd    = $now.minus({ days: 1 }).toISODate();

return users
  .filter(u => u.user_status === 'active')
  .map(user => {
    const uid = user.user_id;
    const userPrescriptions = prescriptions.filter(p => p.user_id === uid && p.status === 'active');
    const userState         = schedule_state.filter(s => s.user_id === uid);
    const nextWeekNudges    = nudges.filter(n =>
      n.user_id === uid &&
      n.scheduled_date >= nextWeekStart &&
      n.scheduled_date <= nextWeekEnd &&
      n.status === 'pending'
    );

    // Per-prescription adherence stats from schedule_state
    const stats = {};
    userPrescriptions.forEach(p => {
      const pNudgeIds = new Set(
        nudges.filter(n => n.prescription_id === p.prescription_id).map(n => n.nudge_id)
      );
      const pState = userState.filter(s => pNudgeIds.has(s.nudge_id));
      const barrierCounts = {};
      pState.forEach(s => { if (s.barrier_tag) barrierCounts[s.barrier_tag] = (barrierCounts[s.barrier_tag] || 0) + 1; });
      const topBarrier = Object.entries(barrierCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || null;
      stats[p.prescription_id] = {
        total_nudges:      pState.length,
        done_count:        pState.filter(s => s.response === 'DONE').length,
        skip_count:        pState.filter(s => ['NOT_YET', 'SKIP'].includes(s.response)).length,
        current_streak:    Math.max(0, ...pState.map(s => parseInt(s.current_streak)  || 0)),
        consecutive_skips: Math.max(0, ...pState.map(s => parseInt(s.consecutive_skips) || 0)),
        top_barrier:       topBarrier
      };
    });

    // Weekly summary text (SDT competence support, zero LLM)
    const lastWeekNudgeIds = new Set(
      nudges.filter(n => n.user_id === uid && n.scheduled_date >= lastWeekStart && n.scheduled_date <= lastWeekEnd)
        .map(n => n.nudge_id)
    );
    const lastWeekDone = userState.filter(s => lastWeekNudgeIds.has(s.nudge_id) && s.response === 'DONE').length;
    const maxStreak    = Math.max(0, ...userState.map(s => parseInt(s.current_streak) || 0));
    const summary_text = 'Week recap: ' + lastWeekDone + '/' + lastWeekNudgeIds.size +
      ' done. Best streak: ' + maxStreak + ' days. Your personalised plan for next week is ready.';

    return { json: { user, userPrescriptions, stats, nextWeekNudges, nextWeekStart, nextWeekEnd, summary_text } };
  });

// Build the Gemini prompt for this user.
// Structured as a flat JSON context object + explicit adaptation rules.
// The LLM must return a JSON array only — no markdown fences, no explanation.
//
// action_text is supplied as read-only context so the rewritten message stays
// about the same behaviour. Adaptation may change HOW a nudge is worded, timed
// and toned; only a clinician may change WHAT the patient is asked to do.

const { user, userPrescriptions, stats, nextWeekNudges, nextWeekStart, nextWeekEnd } = $json;

const ctx = {
  user_profile: {
    age:                  user.age,
    gender:               user.gender,
    activity_level:       user.activity_level,
    primary_goal:         user.primary_goal,
    preferred_nudge_time: user.preferred_nudge_time
  },
  prescriptions: userPrescriptions.map(p => ({
    prescription_id:    p.prescription_id,
    pillar:             p.pillar,
    category:           p.category,
    frequency_per_week: parseInt(p.frequency_per_week),
    adherence:          stats[p.prescription_id]
  })),
  next_week_rows: nextWeekNudges,
  next_week: { start: nextWeekStart, end: nextWeekEnd }
};

const rules = [
  'Return same nudge_ids as next_week_rows. Update ONLY: nudge_type, message_body, message_body_alt, tone_variant, scheduled_time.',
  'Keep UNCHANGED: nudge_id, prescription_id, user_id, pillar, action_text, scheduled_date, template_name, status, week_number.',
  'action_text is the clinician-approved action. Echo it back byte for byte. Never reword, shorten, merge or replace it — the gate restores the stored value and only a clinician may change it.',
  'Write each message so it clearly supports that row action_text.',
  'message_body and message_body_alt each under 200 chars (injected into WhatsApp template {{1}}).',
  'message_body_alt must be the opposite tone to message_body.',
  'consecutive_skips >= 3: use nudge_type reflection or challenge.',
  'current_streak >= 7: use nudge_type affirmation; reference the streak number.',
  'skip rate > 40%: set tone_variant to encouraging.',
  'skip rate <= 40% and current_streak > 0: set tone_variant to neutral_informational.',
  'If top_barrier is time: shift scheduled_time 30 min toward preferred_nudge_time.',
  'Address top_barrier directly in message_body content where possible.',
  'Valid nudge_type values: reminder | reflection | challenge | affirmation',
  'Valid tone_variant values: encouraging | neutral_informational',
  'Valid template_name values: health_plan_reminder | hello_world'
];

const prompt = 'You are a behaviour change assistant. Regenerate next week\'s nudge schedule for this user.\n\nReturn ONLY a valid JSON array — no markdown fences, no explanation.\n\nCONTEXT:\n' +
  JSON.stringify(ctx) +
  '\n\nRULES:\n' + rules.map((r, i) => (i + 1) + '. ' + r).join('\n') +
  '\n\nReturn JSON array only.';

return [{ json: { ...$json, gemini_prompt: prompt } }];

// Validation gate — academically documented design decision.
// Rejects the entire per-user LLM output if any row fails enumeration checks.
// Safe fallback: upstream nudge rows remain unchanged.
//
// action_text is restored from the stored row before anything downstream sees it,
// so weekly adaptation structurally cannot alter the clinician-approved action
// even if the model ignores the prompt. Update Nudge Rows also omits the column.
//
// The gate also passes through user context and summary_text for downstream nodes.

const userCtx  = $('Build Gemini Prompt').item.json;
const response = items[0].json;

const VALID_NUDGE_TYPES = ['reminder', 'reflection', 'challenge', 'affirmation'];
const VALID_PILLARS     = ['nutrition', 'physical_activity', 'sleep', 'stress_management', 'substance_use', 'social_connection'];
const VALID_TONE        = ['encouraging', 'neutral_informational'];
const VALID_TEMPLATES   = ['health_plan_reminder', 'hello_world'];

const base = { user: userCtx.user, summary_text: userCtx.summary_text };
const storedActions = new Map((userCtx.nextWeekNudges || []).map(row => [String(row.nudge_id), row.action_text]));

let new_nudges;
try {
  const text = response.candidates[0].content.parts[0].text;
  new_nudges = JSON.parse(text);
  if (!Array.isArray(new_nudges)) throw new Error('LLM output is not a JSON array');
} catch (e) {
  return [{ json: { ...base, validation_passed: false, error: e.message } }];
}

const errors = [];
let action_text_restored = 0;
new_nudges.forEach((n, i) => {
  if (!n.nudge_id)                                       errors.push('[' + i + '] missing nudge_id');
  if (!VALID_NUDGE_TYPES.includes(n.nudge_type))         errors.push('[' + i + '] invalid nudge_type: ' + n.nudge_type);
  if (!VALID_PILLARS.includes(n.pillar))                 errors.push('[' + i + '] invalid pillar: ' + n.pillar);
  if (n.tone_variant && !VALID_TONE.includes(n.tone_variant)) errors.push('[' + i + '] invalid tone_variant: ' + n.tone_variant);
  if (!VALID_TEMPLATES.includes(n.template_name))        errors.push('[' + i + '] invalid template_name: ' + n.template_name);
  if (!n.message_body || n.message_body.length > 1024)   errors.push('[' + i + '] message_body missing or too long');
  if (n.message_body_alt && n.message_body_alt.length > 1024) errors.push('[' + i + '] message_body_alt too long');
  if (storedActions.has(String(n.nudge_id))) {
    const stored = storedActions.get(String(n.nudge_id));
    if (n.action_text !== stored) action_text_restored += 1;
    n.action_text = stored;
  }
});

if (errors.length) {
  return [{ json: { ...base, validation_passed: false, errors } }];
}

return [{ json: { ...base, validation_passed: true, action_text_restored, new_nudges } }];

// HTTP Request replaced $json with the WhatsApp API response.
// Restore the validated nudge rows from Validation Gate so the
// Sheets update node receives one item per nudge row.
const validated = $('Validation Gate').item.json;
return validated.new_nudges.map(n => ({ json: n }));
